{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
foreach($f in $files){
  Write-Host "=== $f"
  $t=Get-Content $f -Raw -Encoding UTF8
  $ms=[regex]::Matches($t,'`([^`\r\n]+)`')
  $vals=$ms | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
  foreach($v in $vals){ if($v -match '[/\\]|\.md$|\.lua$|\.exe$'){ $exists = Test-Path -LiteralPath $v; Write-Host ("{0,-6} {1}" -f $exists, $v) } }
}","description":"Extract backticked path-like tokens and test existence"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
foreach($f in $files){
  $dir=Split-Path (Resolve-Path $f) -Parent
  Write-Host "=== $f"
  $t=Get-Content $f -Raw -Encoding UTF8
  $ms=[regex]::Matches($t,'`([^`\r\n]+)`')
  $vals=$ms | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
  foreach($v in $vals){
    if($v -match '^[A-Za-z]:' -or $v -match '^(file:|http)' -or $v -match '[*<>|]' -or $v -match '\s'){ continue }
    if($v -notmatch '[/\\]|\.md$|\.lua$|\.exe$|/$'){ continue }
    $r1 = Join-Path (Get-Location) $v
    $r2 = Join-Path $dir $v
    if(-not (Test-Path -LiteralPath $r1) -and -not (Test-Path -LiteralPath $r2)){ Write-Host "MISS  $v" }
    elseif(-not (Test-Path -LiteralPath $r1)){ Write-Host "DIRREL $v" }
  }
}","description":"Resolve path tokens relative to root and file dir"}

{"command":"$idx=@{'docs/project/index.md'='docs/project';'docs/project/building/index.md'='docs/project/building';'docs/project/platform/index.md'='docs/project/platform';'docs/project/sessions/index.md'='docs/project/sessions';'docs/project/building/phase0-protocols/index.md'='docs/project/building/phase0-protocols';'docs/adr/index.md'='docs/adr';'docs/guides/index.md'='docs/guides'}
foreach($k in $idx.Keys){
  $dir=$idx[$k]
  $actual = Get-ChildItem $dir -Filter *.md | Where-Object { $_.Name -ne 'index.md' } | ForEach-Object Name | Sort-Object
  $t=Get-Content $k -Raw -Encoding UTF8
  $listed = [regex]::Matches($t,'`([^`\r\n]+\.md)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
  Write-Host "=== $k"
  Write-Host ("MISSING FROM INDEX: " + (($actual | Where-Object { $listed -notcontains $_ }) -join ', '))
  Write-Host ("LISTED BUT ABSENT: " + (($listed | Where-Object { $actual -notcontains $_ }) -join ', '))
}","description":"Diff each index against its directory"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
