{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
foreach($f in $files){
  $dir=Split-Path (Resolve-Path $f) -Parent
  $t=Get-Content $f -Raw -Encoding UTF8
  $vals=[regex]::Matches($t,'`([^`\r\n]+)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
  foreach($v in $vals){
    if($v -match '^[A-Za-z]:' -or $v -match '^(file:|http)' -or $v -match '[*<>|]' -or $v -match '\s'){ continue }
    if($v -notmatch '[/\\]|\.md$|\.lua$|\.exe$|/$'){ continue }
    if($v -match '\.(md|lua)$' -and $v -notmatch '/'){ continue }
    $r1 = Join-Path (Get-Location) $v
    if(-not (Test-Path -LiteralPath $r1)){ $r2 = Join-Path $dir $v; if(-not (Test-Path -LiteralPath $r2)){ Write-Host "MISS $f -> $v" } else { Write-Host "REL  $f -> $v" } }
  }
}
Write-Host 'done'","description":"Re-resolve path tokens in five docs"}

