{"command":"$idx=@{
 'docs/project/index.md'='docs/project';
 'docs/project/building/index.md'='docs/project/building';
 'docs/project/platform/index.md'='docs/project/platform';
 'docs/project/sessions/index.md'='docs/project/sessions';
 'docs/project/building/phase0-protocols/index.md'='docs/project/building/phase0-protocols';
 'docs/adr/index.md'='docs/adr';
 'docs/guides/index.md'='docs/guides'}
foreach($k in $idx.Keys){
  $dir=$idx[$k]
  $actual = Get-ChildItem $dir -Filter *.md | Where-Object { $_.Name -ne 'index.md' }
  $t=Get-Content $k -Raw -Encoding UTF8
  $notlisted = $actual | Where-Object { $t -notmatch [regex]::Escape($_.Name) } | ForEach-Object Name
  $listed = [regex]::Matches($t,'`(docs/[^`\r\n]+\.md)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
  $absent = $listed | Where-Object { -not (Test-Path -LiteralPath $_) }
  Write-Host "=== $k actual=$($actual.Count) listedRootPaths=$($listed.Count)"
  if($notlisted){ Write-Host ("  NOT LISTED: " + ($notlisted -join ', ')) } else { Write-Host "  every file listed" }
  if($absent){ Write-Host ("  LISTED BUT ABSENT: " + ($absent -join ', ')) } else { Write-Host "  no absent entry" }
}","description":"Re-verify all seven indexes against directories"}

