{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
foreach($f in $files){
  Write-Host "=== $f"
  $t=Get-Content $f -Raw -Encoding UTF8
  [regex]::Matches($t,'`([^`\r\n]+)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique | Where-Object { $_ -match '(^\.\./|/|\.md$|\.lua$)' } | ForEach-Object {
    $v=$_
    $ok = (Test-Path -LiteralPath $v)
    if(-not $ok -and $v -match '^\.\./miliastra-game-template/'){ $ok=$true }
    if(-not $ok){ Write-Host "  UNRESOLVED: $v" }
  }
}
Write-Host 'scan complete'","description":"Final path-resolution scan of the five docs"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
foreach($f in $files){
  $t=Get-Content $f -Raw -Encoding UTF8
  $s=[regex]::Matches($t,'`([^`\r\n]+)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique | Where-Object { $_ -match '\.(md|lua)$|/' }
  $bad=@()
  foreach($v in $s){
    if($v -match '[<>]' -or $v -eq 'file:///' -or $v -eq 'docs/specs/'){ continue }
    if(Test-Path -LiteralPath $v){ continue }
    if($v -match '^\.\./miliastra-game-template/'){ continue }
    $bad += $v
  }
  if($bad){ Write-Host "=== $f"; $bad | ForEach-Object { Write-Host "  $($_)" } }
}
Write-Host 'ok'","description":"Re-scan for unresolved paths"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/project/building/index.md','docs/project/platform/index.md','docs/project/sessions/index.md','docs/project/building/phase0-protocols/index.md','docs/adr/index.md','docs/guides/index.md'
$enc=New-Object System.Text.UTF8Encoding($false,$true)
foreach($f in $files){
  $bytes=[System.IO.File]::ReadAllBytes((Resolve-Path $f))
  try{ $null=$enc.GetString($bytes); $ok='UTF8-ok' }catch{ $ok='UTF8-FAIL' }
  $t=[System.IO.File]::ReadAllText((Resolve-Path $f),[System.Text.Encoding]::UTF8)
  $cjk = ($t -match '千星奇域'),($t -match 'Sandbox-City')
  "$ok`t$($bytes.Length)`t$f`tCJK=$($cjk -join ',')"
}","description":"Verify UTF-8 validity and CJK integrity"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
foreach($f in $files){
  $i=0
  Get-Content $f -Encoding UTF8 | ForEach-Object { $i++
    if($_ -match '§'){ Write-Host "$f`:$i`t$($_.Trim())" }
  }
}
Write-Host '=== also check "AGENTS.md" mentions'
Select-String -Path PRD.md,CONTEXT.md,docs/project/index.md,docs/guides/index.md -Pattern 'AGENTS\.md' | ForEach-Object { "$($_.Filename):$($_.LineNumber): $($_.Line.Trim())" }","description":"List all section refs and AGENTS.md mentions"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
Write-Host '--- unresolved path tokens'
foreach($f in $files){
  $t=Get-Content $f -Raw -Encoding UTF8
  [regex]::Matches($t,'`([^`\r\n]+)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique | Where-Object { $_ -match '\.(md|lua)$|/' } | ForEach-Object {
    $v=$_
    if($v -match '[<>]' -or $v -eq 'file:///'){ return }
    if(Test-Path -LiteralPath $v){ return }
