Write-Host '--- section refs'
foreach($f in $files){ Get-Content $f -Encoding UTF8 | Select-String -Pattern '§' | ForEach-Object { "  $f : $($_.Line.Trim())" } }","description":"Final unresolved-path and section-ref scan"}

{"command":"$enc=New-Object System.Text.UTF8Encoding($false,$true)
$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/project/building/index.md','docs/project/platform/index.md','docs/project/sessions/index.md','docs/project/building/phase0-protocols/index.md','docs/adr/index.md','docs/guides/index.md','docs/plans/2026-10-24-template-resync/00-log.md'
foreach($f in $files){
  $b=[System.IO.File]::ReadAllBytes((Resolve-Path $f))
  try{$null=$enc.GetString($b);$ok='ok'}catch{$ok='FAIL'}
  "{0}`t{1}`t{2} lines`t{3}" -f $ok,$f,(Get-Content $f).Count,$b.Length
}
Write-Host '--- scope file count still 74'
$n=(@('AGENTS.md','CONTEXT.md','PRD.md') + (Get-ChildItem docs\project,docs\guides,docs\adr -Recurse -Filter *.md | ForEach-Object FullName)).Count; $n","description":"Validate UTF-8 and line counts of edited files"}

{"command":"$files='AGENTS.md','CONTEXT.md','PRD.md','docs/project/index.md','docs/guides/index.md'
Write-Host '--- unresolved path tokens (excluding external template + explicit patterns)'
foreach($f in $files){
  $t=Get-Content $f -Raw -Encoding UTF8
  [regex]::Matches($t,'`([^`\r\n]+)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique | Where-Object { $_ -match '\.(md|lua)$|/' } | ForEach-Object {
    $v=$_
    if($v -eq 'file:///' -or $v -match '<!--'){ return }
    if(Test-Path -LiteralPath $v){ return }
    if($v -match '^\.\./miliastra-game-template/'){ return }
    Write-Host "  $f -> $v"
  }
}
Write-Host '--- angle-bracket path tokens'
foreach($f in $files){ $t=Get-Content $f -Raw -Encoding UTF8; [regex]::Matches($t,'`[^`]*<[^`]*`') | ForEach-Object { "  $f : $($_.Value)" } }","description":"Final scan for unresolved and angle-bracket paths"}

{"command":"$idx=@{'docs/project/index.md'='docs/project';'docs/project/building/index.md'='docs/project/building';'docs/project/platform/index.md'='docs/project/platform';'docs/project/sessions/index.md'='docs/project/sessions';'docs/project/building/phase0-protocols/index.md'='docs/project/building/phase0-protocols';'docs/adr/index.md'='docs/adr';'docs/guides/index.md'='docs/guides'}
$allgood=$true
foreach($k in $idx.Keys){
  $dir=$idx[$k]
  $actual=Get-ChildItem $dir -Filter *.md | Where-Object {$_.Name -ne 'index.md'}
  $t=Get-Content $k -Raw -Encoding UTF8
  $notlisted=@($actual | Where-Object { $t -notmatch [regex]::Escape($_.Name) })
  $listed=@([regex]::Matches($t,'`(docs/[^`\r\n]+\.md)`') | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
  $absent=@($listed | Where-Object { -not (Test-Path -LiteralPath $_) })
  if($notlisted.Count -or $absent.Count){ $allgood=$false }
  "{0,-50} files={1,2} listed={2,2} notlisted={3} absent={4}" -f $k,$actual.Count,$listed.Count,$notlisted.Count,$absent.Count
}
Write-Host "ALL INDEXES OK: $allgood"
$enc=New-Object System.Text.UTF8Encoding($false,$true)
$bad=0
$files=@('AGENTS.md','CONTEXT.md','PRD.md') + (Get-ChildItem docs\project,docs\guides,docs\adr -Recurse -Filter *.md | ForEach-Object FullName) + 'docs\plans\2026-10-24-template-resync\00-log.md'
foreach($f in $files){ $b=[System.IO.File]::ReadAllBytes((Resolve-Path $f)); try{$null=$enc.GetString($b)}catch{$bad++;Write-Host "UTF8 FAIL $f"} }
Write-Host "UTF8 failures: $bad of $($files.Count)"","description":"Final index and UTF-8 verification"}

{"command":"$t='C:\Users\AAAAA\Desktop\miliastra-game-template'
